validator:
function validate(input) {
  const [{ Products = [] }] = input;
  const stores = ['store1', 'store2', 'store3'], seen = new Set();
  for (const [id, store, price] of Products) {
    if (id === null || price === null) return 'product_id and price may not be null.';
    if (!stores.includes(store)) return `store must be store1, store2 or store3, not ${store}.`;
    if (price < 0) return `Price ${price} is negative.`;
    const key = `${id}|${store}`;
    if (seen.has(key)) return `Product ${id} has two prices in ${store}.`;
    seen.add(key);
  }
  return null;
}

generator:
function generate(rand, size) {
  const small = size === 'small';
  const pick = (n) => Math.floor(rand() * n);
  const stores = ['store1', 'store2', 'store3'];
  const prices = [0, 50, 70, 80, 95, 100, 105];
  const limit = small ? pick(9) : 2000;
  const Products = [];
  for (let id = small ? pick(3) : 1; Products.length < limit; id += small ? 1 + pick(3) : 1) {
    // Each product is sold in a non-empty random subset of the stores.
    let mask = 0;
    while (mask === 0) mask = pick(8);
    for (let s = 0; s < 3 && Products.length < limit; s++) {
      if (mask & (1 << s)) Products.push([id, stores[s], small ? prices[pick(prices.length)] : pick(1000)]);
    }
  }
  for (let i = Products.length - 1; i > 0; i--) { const j = pick(i + 1); [Products[i], Products[j]] = [Products[j], Products[i]]; }
  return [{ Products }];
}
